package dev.hexora.controller;
import dev.hexora.dto.request.ProfileRequest; import dev.hexora.dto.response.*; import dev.hexora.service.ProfileService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/profile") public class ProfileController {private final ProfileService s;public ProfileController(ProfileService s){this.s=s;} @GetMapping("/public") ApiResponse<?> pub(){return ApiResponse.success(s.all(org.springframework.data.domain.Sort.by("createdAt").descending()).stream().findFirst().orElse(null));} @GetMapping("/public/{id}") ApiResponse<?> pubId(@PathVariable Long id){return ApiResponse.success(s.find(id));} @GetMapping ApiResponse<?> all(){return ApiResponse.success(s.all(org.springframework.data.domain.Sort.by("createdAt").descending()));} @GetMapping("/{id}") ApiResponse<?> one(@PathVariable Long id){return ApiResponse.success(s.find(id));} @PostMapping ApiResponse<?> create(@Valid @RequestBody ProfileRequest r){return ApiResponse.created(s.create(r));} @PutMapping("/{id}") ApiResponse<?> update(@PathVariable Long id,@Valid @RequestBody ProfileRequest r){return ApiResponse.success(s.update(id,r));} @DeleteMapping("/{id}") ResponseEntity<?> del(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
